mapper.select:
select t.typecode as typecode, isnull(nullif(l.labelname, ''), isnull(t.sourcename, '')) as typename, isnull(lg.labelname, '') as groupname from ECOLOGY_MESSAGE_TYPE t left join ECOLOGY_MESSAGE_GROUP g on g.id = t.ecology_message_groupid
left join HtmlLabelInfo l on l.indexid = t.typename and l.languageid = #{lang} left join HtmlLabelInfo lg on lg.indexid = g.groupname and lg.languageid = #{lang}
order by case when t.typecode not like '%[^0-9]%' and t.typecode <> '' then cast(t.typecode as int) else 2147483647 end, t.typecode
